import {createRequire} from 'node:module';
// Run inside the actual public 2.x API image after its own migrations. Uses
// its generated Prisma model and its own scrypt helper, not a second schema.
const require=createRequire('/app/packages/db/package.json');
const {createJiti}=require('jiti');
const jiti=createJiti('/app/packages/db/');
// schema.prisma uses provider=prisma-client with custom TS ESM output. The
// default @prisma/client entry is not generated by this public image.
const {PrismaClient}=await jiti.import('/app/packages/db/src/generated/prisma/client.ts');
const {hashPassword,verifyPassword}=await jiti.import('/app/packages/common/server/crypto.ts');
const db=new PrismaClient({log:[]});
const uuid=name=>{const value=process.env[name];if(!/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/.test(value??''))throw new Error(name+' must be an explicit UUID');return value;};
const secret=name=>{const value=process.env[name];if(!value||value.length<32)throw new Error(name+' must be explicit');return value;};
const organizationId=uuid('OPENPANEL_ORGANIZATION_ID'),projectId=uuid('OPENPANEL_PROJECT_ID');
// OpenPanel's native hourly cleanup removes organizations without an
// org:admin member, including self-hosted projects. This service contact is
// deliberately not a login user, credential account, invite, or session.
const ownerEmail=process.env.OPENPANEL_OWNER_EMAIL;
if(!/^[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$/.test(ownerEmail??''))throw new Error('OPENPANEL_OWNER_EMAIL must be an explicit service contact');
try{
 await db.$transaction(async tx=>{
  await tx.organization.upsert({where:{id:organizationId},create:{id:organizationId,name:'银河使用分析',timezone:'Asia/Shanghai'},update:{}});
  const owners=await tx.member.findMany({where:{organizationId,email:ownerEmail}});
  if(!owners.some(row=>row.role==='org:admin')){
   if(owners.length)throw new Error('OpenPanel service ownership drift');
   await tx.member.create({data:{organizationId,email:ownerEmail,role:'org:admin',userId:null,meta:{purpose:'galaxy-internal-service-owner',interactiveLogin:false}}});
  }
  const project=await tx.project.findUnique({where:{id:projectId}});
  if(project&&project.organizationId!==organizationId)throw new Error('OpenPanel project ownership mismatch');
  if(!project)await tx.project.create({data:{id:projectId,organizationId,name:'银河网站',types:['website'],cors:[],crossDomain:false,allowUnsafeRevenueTracking:false,filters:[]}});
  for(const[type,prefix]of[['write','OPENPANEL_WRITE'],['read','OPENPANEL_READ']]){
   const id=uuid(prefix+'_CLIENT_ID'),plain=secret(prefix+'_CLIENT_SECRET'),current=await tx.client.findUnique({where:{id}});
   if(current){if(current.organizationId!==organizationId||current.projectId!==projectId||current.type!==type||current.ignoreCorsAndSecret||!current.secret||!await verifyPassword(plain,current.secret))throw new Error('OpenPanel client ownership or credential drift');}
   else await tx.client.create({data:{id,organizationId,projectId,name:'Galaxy '+type,type,secret:await hashPassword(plain),ignoreCorsAndSecret:false}});
  }
 });
 // No credential, client ID, event payload or resolved environment is printed.
 console.info(JSON.stringify({bootstrap:'ready',source:'native-openpanel-2-prisma',clients:['write','read'],ownership:'native-non-login-member'}));
}finally{await db.$disconnect();}
